import numpy as np
from scipy.optimize import linear_sum_assignment

class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem['source_weights'])
        b = np.asarray(problem['target_weights'])
        M = np.asarray(problem['cost_matrix'])
        # Benchmark instances have equally weighted distributions of equal size.  Their
        # transportation LP is therefore the linear assignment problem.
        if M.shape[0] == M.shape[1] and np.all(a == a[0]) and np.all(b == b[0]):
            r, c = linear_sum_assignment(M)
            G = np.zeros(M.shape, dtype=np.float64)
            G[r, c] = a
            return {'transport_plan': G}
        # General fallback.
        import ot
        return {'transport_plan': ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)}
